-- Run after existing category fixtures in a disposable local database only.
BEGIN;
SELECT test.assert_true(NOT EXISTS(SELECT FROM private.service_categories WHERE execution_level IS NOT NULL),'levels: legacy categories remain pending without invented classification');
SELECT test.assert_true(NOT has_table_privilege('authenticated','private.request_preintakes','SELECT,INSERT,UPDATE,DELETE') AND NOT has_table_privilege('authenticated','private.request_level_exceptions','SELECT,INSERT,UPDATE,DELETE'),'levels: intake and exceptions private ACL');
INSERT INTO private.team_member_permissions(membership_id,permission_code) VALUES('00000000-0000-4000-b000-000000000733','requests.read'),('00000000-0000-4000-b000-000000000733','requests.create') ON CONFLICT DO NOTHING;
SELECT test.assert_true(private.member_execution_level((SELECT m FROM public.memberships m WHERE id='00000000-0000-4000-b000-000000000733'),3) AND NOT private.member_execution_level((SELECT m FROM public.memberships m WHERE id='00000000-0000-4000-b000-000000000733'),1) AND NOT private.member_execution_level((SELECT m FROM public.memberships m WHERE id='00000000-0000-4000-b000-000000000733'),2),'levels: employee general only by default');
INSERT INTO private.team_member_permissions(membership_id,permission_code) VALUES('00000000-0000-4000-b000-000000000733','requests.level1');
SELECT test.assert_true(private.member_execution_level((SELECT m FROM public.memberships m WHERE id='00000000-0000-4000-b000-000000000733'),1) AND NOT private.member_execution_level((SELECT m FROM public.memberships m WHERE id='00000000-0000-4000-b000-000000000733'),2),'levels: grant1 independent of2 without changing employee role');
SELECT test.assert_true(private.member_execution_level((SELECT m FROM public.memberships m WHERE id='00000000-0000-4000-b000-000000000731'),1) AND private.member_execution_level((SELECT m FROM public.memberships m WHERE id='00000000-0000-4000-b000-000000000731'),2) AND private.member_execution_level((SELECT m FROM public.memberships m WHERE id='00000000-0000-4000-b000-000000000731'),3),'levels: owner all three');
SET ROLE authenticated;
SET request.jwt.claims='{"sub":"00000000-0000-4000-a000-000000000731","session_id":"00000000-0000-4000-c000-000000000731"}';
SELECT test.expect_error($q$SELECT public.service_categories_command('00000000-0000-4000-e000-000000000731','{"kind":"create","name":"Level test","reason":"Test"}',gen_random_uuid())$q$,'PT422','levels: create without level rejected');
SELECT test.assert_true(public.service_categories_command('00000000-0000-4000-e000-000000000731','{"kind":"create","name":"Level test","execution_level":2,"reason":"Test"}',gen_random_uuid())->>'can_manage'='true','levels: explicit category created');
RESET ROLE;
CREATE TEMP TABLE level_test_request AS SELECT NULL::uuid id;
SET ROLE authenticated;
SET request.jwt.claims='{"sub":"00000000-0000-4000-a000-000000000733","session_id":"00000000-0000-4000-c000-000000000733"}';
RESET ROLE;
UPDATE level_test_request SET id=(public.request_preintake_create('00000000-0000-4000-e000-000000000731',jsonb_build_object('origin','presencial','title','Collected','message','Customer statement','customer_id',NULL,'category_id',(SELECT id FROM private.service_categories WHERE office_id='00000000-0000-4000-e000-000000000731' AND name='Level test'),'internal_note','Retained collection note'),gen_random_uuid())->>'id')::uuid;
SELECT test.assert_true((SELECT private.request_can_collect(r,m) AND NOT private.request_can_work(r,m) FROM public.requests r CROSS JOIN public.memberships m WHERE r.id=(SELECT id FROM level_test_request) AND m.id='00000000-0000-4000-b000-000000000733'),'levels: nonenabled employee collects without execution');
SELECT public.request_preintake_update('00000000-0000-4000-e000-000000000731',(SELECT id FROM level_test_request),(SELECT version FROM public.requests WHERE id=(SELECT id FROM level_test_request)),jsonb_build_object('title','Updated collection','message','Updated details','customer_id',NULL,'internal_note','More collection information')) IS NOT NULL;
SELECT test.assert_true((SELECT title='Updated collection' AND message='Updated details' FROM public.requests WHERE id=(SELECT id FROM level_test_request)) AND EXISTS(SELECT FROM private.request_preintake_events WHERE request_id=(SELECT id FROM level_test_request) AND details->>'title'='Collected'),'levels: collection edit preserves previous private content and authorship');
SELECT public.request_preintake_handoff('00000000-0000-4000-e000-000000000731',(SELECT id FROM level_test_request),(SELECT version FROM public.requests WHERE id=(SELECT id FROM level_test_request)),'Forward to enabled executor');
SELECT test.assert_true((SELECT NOT private.request_can_collect(r,m) AND r.created_by=m.user_id AND r.status='aguardando_responsavel' AND r.assignee_id IS NULL FROM public.requests r CROSS JOIN public.memberships m WHERE r.id=(SELECT id FROM level_test_request) AND m.id='00000000-0000-4000-b000-000000000733'),'levels: handoff closes collection and keeps authorship without unqualified dispatch');
SELECT test.expect_error($q$SELECT public.request_preintake_update('00000000-0000-4000-e000-000000000731',(SELECT id FROM level_test_request),3,jsonb_build_object('title','Forbidden','message','','customer_id',NULL,'internal_note',''))$q$,'PT403','levels: collector cannot edit after handoff');
SET request.jwt.claims='{"sub":"00000000-0000-4000-a000-000000000731","session_id":"00000000-0000-4000-c000-000000000731"}';
UPDATE public.requests SET assignee_id='00000000-0000-4000-b000-000000000731',status='aberto' WHERE id=(SELECT id FROM level_test_request);
SELECT public.request_level_transfer('00000000-0000-4000-e000-000000000731',(SELECT id FROM level_test_request),(SELECT version FROM public.requests WHERE id=(SELECT id FROM level_test_request)),'00000000-0000-4000-b000-000000000733','Authorized exception only this request') IS NOT NULL;
SELECT test.assert_true((SELECT private.request_can_work(r,m) FROM public.requests r CROSS JOIN public.memberships m WHERE r.id=(SELECT id FROM level_test_request) AND m.id='00000000-0000-4000-b000-000000000733') AND NOT private.team_permissions_for_member('00000000-0000-4000-b000-000000000733') @> ARRAY['requests.level2'] AND EXISTS(SELECT FROM public.audit_events WHERE office_id='00000000-0000-4000-e000-000000000731' AND action='requests.level_exception_authorized'),'levels: transfer exception permits only request without global level grant and is audited');
SELECT public.request_level_revoke('00000000-0000-4000-e000-000000000731',(SELECT id FROM level_test_request),(SELECT version FROM public.requests WHERE id=(SELECT id FROM level_test_request)),'End specific authorization') IS NOT NULL;
SELECT test.assert_true((SELECT NOT private.request_can_work(r,m) FROM public.requests r CROSS JOIN public.memberships m WHERE r.id=(SELECT id FROM level_test_request) AND m.id='00000000-0000-4000-b000-000000000733'),'levels: exception revocation immediately blocks execution');
ROLLBACK;
